    29  static bool is_valid_chroma(uint8_t chroma) {
    30    switch (chroma) {
    31      case heif_chroma_monochrome:
    32      case heif_chroma_420:
    33      case heif_chroma_422:
    34      case heif_chroma_444:
    35      case heif_chroma_interleaved_RGB:
    36      case heif_chroma_interleaved_RGBA:
    37      case heif_chroma_interleaved_RRGGBB_BE:
    38      case heif_chroma_interleaved_RRGGBBAA_BE:
    39      case heif_chroma_interleaved_RRGGBB_LE:
    40      case heif_chroma_interleaved_RRGGBBAA_LE:
    41        return true;
    42      default:
    43        return false;
    44    }
    45  }
    46
    47  static bool is_valid_colorspace(uint8_t colorspace) {
    48    switch (colorspace) {
    49      case heif_colorspace_YCbCr:
    50      case heif_colorspace_RGB:
    51      case heif_colorspace_monochrome:
    52        return true;
    53      default:
    54        return false;
    55    }
    56  }
    57
    58  static bool read_plane(heif::BitstreamRange* range,
    59      std::shared_ptr<heif::HeifPixelImage> image, heif_channel channel,
    60      int width, int height, int bit_depth) {
    61    if (width <= 0 || height <= 0) {
    62      return false;
    63    }
    64    if (!range->prepare_read(static_cast<uint64_t>(width) * height)) {
    65      return false;
    66    }
    67    if (!image->add_plane(channel, width, height, bit_depth)) {
    68      return false;
    69    }
    70    int stride;
    71    uint8_t* plane = image->get_plane(channel, &stride);
    72    assert(stride >= width);
    73    auto stream = range->get_istream();
    74    for (int y = 0; y < height; y++, plane += stride) {
    75      assert(stream->read(plane, width));
    76    }
    77    return true;
    78  }
    79
    80  static bool read_plane_interleaved(heif::BitstreamRange* range,
    81      std::shared_ptr<heif::HeifPixelImage> image, heif_channel channel,
    82      int width, int height, int bit_depth, int comps) {
    83    if (width <= 0 || height <= 0) {
    84      return false;
    85    }
    86    if (!range->prepare_read(static_cast<uint64_t>(width) * height * comps)) {
    87      return false;
    88    }
    89    if (!image->add_plane(channel, width, height, bit_depth)) {
    90      return false;
    91    }
    92    int stride;
    93    uint8_t* plane = image->get_plane(channel, &stride);
    94    assert(stride >= width * comps);
    95    auto stream = range->get_istream();
    96    for (int y = 0; y < height; y++, plane += stride) {
    97      assert(stream->read(plane, width * comps));
    98    }
    99    return true;
   100  }
