   102  extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size) {
   103    auto reader = std::make_shared<heif::StreamReader_memory>(data, size, false);
   104    heif::BitstreamRange range(reader, size);
   105
   106    int width;
   107    int height;
   108    int bit_depth;
   109    bool alpha;
   110    uint8_t in_chroma;
   111    uint8_t in_colorspace;
   112    uint8_t out_chroma;
   113    uint8_t out_colorspace;
   114    if (!range.prepare_read(10)) {
   115      return 0;
   116    }
   117
   118    width = range.read16();
   119    height = range.read16();
   120    bit_depth = range.read8();
   121    alpha = range.read8() == 1;
   122    in_chroma = range.read8();
   123    in_colorspace = range.read8();
   124    out_chroma = range.read8();
   125    out_colorspace = range.read8();
   126
   127    // Width / height must be a multiple of 2.
   128    if (width == 0 || height == 0 || (width & 1) != 0 || (height & 1) != 0) {
   129      return 0;
   130    }
   131
   132    switch (bit_depth) {
   133      case 8:
   134        break;
   135      default:
   136        // TODO: Add support for more color depths.
   137        return 0;
   138    }
   139
   140    if (!is_valid_chroma(in_chroma) || !is_valid_colorspace(in_colorspace) ||
   141        !is_valid_chroma(out_chroma) || !is_valid_colorspace(out_colorspace)) {
   142      return 0;
   143    }
   144
   145    auto in_image = std::make_shared<heif::HeifPixelImage>();
   146    in_image->create(width, height, static_cast<heif_colorspace>(in_colorspace),
   147        static_cast<heif_chroma>(in_chroma));
   148
   149    switch (in_colorspace) {
   150      case heif_colorspace_YCbCr:
   151        switch (in_chroma) {
   152          case heif_chroma_420:
   153            if (!read_plane(&range, in_image, heif_channel_Y,
   154                width, height, bit_depth)) {
   155              return 0;
   156            }
   157            if (!read_plane(&range, in_image, heif_channel_Cb,
   158                width / 2, height / 2, bit_depth)) {
   159              return 0;
   160            }
   161            if (!read_plane(&range, in_image, heif_channel_Cr,
   162                width / 2, height / 2, bit_depth)) {
   163              return 0;
   164            }
   165            break;
   166          case heif_chroma_422:
   167            if (!read_plane(&range, in_image, heif_channel_Y,
   168                width, height / 2, bit_depth)) {
   169              return 0;
   170            }
   171            if (!read_plane(&range, in_image, heif_channel_Cb,
   172                width / 2, height / 2, bit_depth)) {
   173              return 0;
   174            }
   175            if (!read_plane(&range, in_image, heif_channel_Cr,
   176                width / 2, height / 2, bit_depth)) {
   177              return 0;
   178            }
   179            break;
   180          case heif_chroma_444:
   181            if (!read_plane(&range, in_image, heif_channel_Y,
   182                width, height, bit_depth)) {
   183              return 0;
   184            }
   185            if (!read_plane(&range, in_image, heif_channel_Cb,
   186                width, height, bit_depth)) {
   187              return 0;
   188            }
   189            if (!read_plane(&range, in_image, heif_channel_Cr,
   190                width, height, bit_depth)) {
   191              return 0;
   192            }
   193            break;
   194          default:
   195            return 0;
   196        }
   197        break;
   198      case heif_colorspace_RGB:
   199        switch (in_chroma) {
   200          case heif_chroma_interleaved_RGB:
   201            if (!read_plane_interleaved(&range, in_image,
   202                heif_channel_interleaved, width, height, bit_depth, 3)) {
   203              return 0;
   204            }
   205            break;
   206          case heif_chroma_interleaved_RGBA:
   207            if (!read_plane_interleaved(&range, in_image,
   208                heif_channel_interleaved, width, height, bit_depth, 4)) {
   209              return 0;
   210            }
   211            alpha = false;  // Already part of interleaved data.
   212            break;
   213          default:
   214            // TODO: Support other RGB chromas.
   215            return 0;
   216        }
   217        break;
   218      case heif_colorspace_monochrome:
   219        if (in_chroma != heif_chroma_monochrome) {
   220          return 0;
   221        }
   222        if (!read_plane(&range, in_image, heif_channel_Y,
   223            width, height, bit_depth)) {
   224          return 0;
   225        }
   226        break;
   227      default:
   228        assert(false);
   229    }
   230
   231    if (alpha) {
   232      if (!read_plane(&range, in_image, heif_channel_Alpha,
   233          width, height, bit_depth)) {
   234        return 0;
   235      }
   236    }
   237
   238    auto out_image = convert_colorspace(in_image,
   239        static_cast<heif_colorspace>(out_colorspace),
   240        static_cast<heif_chroma>(out_chroma));
   241    if (!out_image) {
   242      // Conversion is not supported.
   243      return 0;
   244    }
   245
   246    assert(out_image->get_width() == width);
   247    assert(out_image->get_height() == height);
   248    assert(out_image->get_chroma_format() ==
   249           static_cast<heif_chroma>(out_chroma));
   250    assert(out_image->get_colorspace() ==
   251           static_cast<heif_colorspace>(out_colorspace));
   252    return 0;
   253  }
